9	/// A Pulley bytecode disassembler.
10	///
11	/// This is implemented as an `OpVisitor`, where you pass a `Disassembler` to a
12	/// `Decoder` in order to disassemble instructions from a bytecode stream.
13	///
14	/// Alternatively, you can use the `Disassembler::disassemble_all` method to
15	/// disassemble a complete bytecode stream.
16	pub struct Disassembler<'a> {
17	    raw_bytecode: &'a [u8],
18	    bytecode: SafeBytecodeStream<'a>,
19	    disas: String,
20	    start_offset: usize,
21	    start: usize,
22	    temp: String,
23	    offsets: bool,
24	    hexdump: bool,
25	}
26	
27	impl<'a> Disassembler<'a> {
28	    /// Disassemble every instruction in the given bytecode stream.
29	    pub fn disassemble_all(bytecode: &'a [u8]) -> Result<String> {
30	        let mut disas = Self::new(bytecode);
31	        Decoder::decode_all(&mut disas)?;
32	        Ok(disas.disas)
33	    }
34	
35	    /// Create a new `Disassembler` that can be used to incrementally
36	    /// disassemble instructions from the given bytecode stream.
37	    pub fn new(bytecode: &'a [u8]) -> Self {
38	        Self {
39	            raw_bytecode: bytecode,
40	            bytecode: SafeBytecodeStream::new(bytecode),
41	            disas: String::new(),
42	            start: 0,
43	            start_offset: 0,
44	            temp: String::new(),
45	            offsets: true,
46	            hexdump: true,
47	        }
48	    }
49	
50	    /// Whether to prefix each instruction's disassembly with its offset.
51	    ///
52	    /// True by default.
53	    pub fn offsets(&mut self, offsets: bool) -> &mut Self {
54	        self.offsets = offsets;
55	        self
56	    }
57	
58	    /// Whether to include a hexdump of the bytecode in the disassembly.
59	    ///
60	    /// True by default.
61	    pub fn hexdump(&mut self, hexdump: bool) -> &mut Self {
62	        self.hexdump = hexdump;
63	        self
64	    }
65	
66	    /// Configures the offset that this function starts from, if it doesn't
67	    /// start from 0.
68	    ///
69	    /// This can possibly be useful when a single function at a time is being
70	    /// disassembled.
71	    pub fn start_offset(&mut self, offset: usize) -> &mut Self {
72	        self.start_offset = offset;
73	        self
74	    }
75	
76	    /// Get the disassembly thus far.
77	    pub fn disas(&self) -> &str {
78	        &self.disas
79	    }
80	
81	    fn disas_op(&mut self, mnemonic: &str, operands: &[&dyn Disas]) {
82	        write!(&mut self.temp, "{mnemonic}").unwrap();
83	        for (i, val) in operands.iter().enumerate() {
84	            if i > 0 {
85	                write!(&mut self.temp, ",").unwrap();
86	            }
87	            write!(&mut self.temp, " ").unwrap();
88	            val.disas(self.start + self.start_offset, &mut self.temp);
89	        }
90	    }
91	
92	    fn disas_br_table32(&mut self, reg: XReg, amt: u32) {
93	        self.disas_op("br_table32", &[&reg, &amt]);
94	        for _ in 0..amt {
95	            self.after_visit();
96	            self.start = self.bytecode.position();
97	            if let Ok(offset) = PcRelOffset::decode(self.bytecode()) {
98	                offset.disas(self.start + self.start_offset, &mut self.temp);
99	            }
100	        }
101	    }
102	}
