196	fn disas_list<T: Disas>(position: usize, disas: &mut String, iter: impl IntoIterator<Item = T>) {
197	    let mut iter = iter.into_iter();
198	    let Some(first) = iter.next() else { return };
199	    first.disas(position, disas);
200	
201	    for item in iter {
202	        write!(disas, ", ").unwrap();
203	        item.disas(position, disas);
204	    }
205	}
